_JS="function switchTab(id,b){document.querySelectorAll('.tab-panel').forEach(p=>p.classList.remove('active'));document.querySelectorAll('.tab-btn').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-selected','false')});var t=document.getElementById('tab-'+id);if(t)t.classList.add('active');if(b){b.classList.add('active');b.setAttribute('aria-selected','true')}}";_esc=lambda v:html.escape('' if v is None else str(v),quote=True);_cd=lambda v:f'<code>{_esc(v)}</code>';_b=lambda c,t:f'<span class="b {c}">{_esc(t)}</span>';_ch=lambda k,v:f'<div class="it"><div class="k">{k}</div><div class="v">{_esc(v)}</div></div>';_kp=lambda k,v,s:f'<div class="kp"><div class="kl">{k}</div><div class="kv">{v}</div><div class="ks">{s}</div></div>';_tr=lambda*cs:'<tr>'+''.join((f'<td>{c}</td>' for c in cs))+'</tr>';_tbl=lambda cols,rows:f"""<div class="tw"><table><thead><tr>{''.join((f'<th>{c}</th>' for c in cols))}</tr></thead><tbody>{''.join(rows) or f'<tr><td colspan={len(cols)}><em>None</em></td></tr>'}</tbody></table></div>""";_sec=lambda t,b,body:f'<section class="pn"><h2><span>{t}</span>{b}</h2>{body}</section>'
class HTMLDashboard:
 def __init__(self):self._m,self._f=(MitreMapper(),ForensicExporter())
 def render(self,*,entries,scope_info,chain_result,compliance,signature,generated_at,merkle_info=None,sarif_summary=None,manifest_data=None,circuit_breaker_info=None):
  mi=merkle_info or self._f.build_merkle_tree([str(e.get('entry_hash',''))for e in entries if e.get('entry_hash')]);mr=str(mi.get('merkle_root',GENESIS_HASH))
  if sarif_summary is None:_,cnt=self._f.build_sarif_payload(entries=entries,scope_info=scope_info);sarif_summary={'total_findings':sum(cnt.values()),'rule_counts':cnt}
  sc=sarif_summary.get('rule_counts',{});trp=sum((1 for e in entries if e.get('status')=='KILL_SWITCH_TRIPPED'));rst=sum((1 for e in entries if e.get('status')=='CIRCUIT_RESET'));cb_st=str((circuit_breaker_info or{}).get('state')or('OPEN (LOCKED)' if trp>rst else 'CLOSED (ARMED)'));ags=sorted({str((e.get('ai_disclosure')or{}).get('agent_id','')).strip()for e in entries}-{''})or['pentest-scribe'];mds=sorted({str((e.get('ai_disclosure')or{}).get('model','')).strip()for e in entries}-{''})or['os-lab-auditor'];steps,ais,shs=([],[],[])
  for e in entries:
   seq,st,cmd=(f"<b>#{_esc(e.get('seq', '?'))}</b>",str(e.get('status','')),str(e.get('command','')));mit=e.get('mitre')if isinstance(e.get('mitre'),dict)and e['mitre'].get('technique_id')else self._m.map_step(cmd,status=st).to_dict();rsk,rc=(str(mit.get('risk_level',e.get('risk_level','LOW'))),int(e.get('redacted_count')or 0));steps.append(_tr(seq,_cd(e.get('timestamp','')),_cd(e.get('target','')),_cd(cmd),f"{_b('bp', mit.get('technique_id', 'T1595'))} {_esc(mit.get('technique_name', ''))}",_esc(mit.get('tactic_name','')),_b(_RC.get(rsk,'rl'),rsk),_b('ba',f'{rc} masked')if rc else _b('','0'),_b(_SC.get(st,''),st),_esc(e.get('output_summary',''))));ai=e.get('ai_disclosure')or{};ais.append(_tr(seq,_cd(ai.get('agent_id','-')),_cd(ai.get('model','-')),_cd(ai.get('tool_name','-')),_b('bg' if ai.get('human_approved')else 'br',str(bool(ai.get('human_approved'))).upper()),_cd(str(ai.get('prompt_hash','-'))[:20]),_esc(ai.get('reasoning','-'))))
   if st in('REFUSED_PROMPT_INJECTION','KILL_SWITCH_TRIPPED','CIRCUIT_RESET'):shs.append(_tr(seq,_b(_SC.get(st,''),st),_cd(e.get('target','-')),_cd(cmd),_cd(ai.get('agent_id','-')),_esc(e.get('output_summary',''))))
  cok=chain_result.valid;nodes=[f'<div class="cn"><b>GENESIS</b><br>{_esc(GENESIS_HASH[:16])}</div>']+[f"""&rarr;<div class="cn"><b>#{_esc(e.get('seq', '?'))} ({_esc(e.get('status', ''))})</b><br>{_esc(str(e.get('entry_hash', ''))[:12])}</div>""" for e in entries]+[f"""&rarr;<div class="cn {('ve' if cok else 'be')}"><b>{_esc('CHAIN VALID' if cok else f'TAMPER_DETECTED ({chain_result.failed_seq})')}</b><br>{_esc(chain_result.head_hash[:16])}</div>"""];mrows=[_tr(_cd(a.get('filename','-')),f"{_esc(a.get('bytes', 0))}B",_cd(a.get('sha256','-')))for a in(manifest_data or{}).get('artifacts',[])];score,pb=(int(compliance.get('score',100)),int(compliance.get('prompt_injection_blocks',0)));kpis=''.join([_kp('Steps',str(int(compliance.get('total_steps',len(entries)))),'Audited'),_kp('In-Scope',str(int(compliance.get('in_scope_steps',0))),'Lab'),_kp('Blocked',str(int(compliance.get('blocked_steps',0))),f'Shield:{pb}'),_kp('DLP',str(int(compliance.get('redacted_secrets',0))),'Masked'),_kp('Score',f'{score}/100',_esc(compliance.get('grade','A+'))),_kp('Breaker',_esc(cb_st),f'T:{trp} R:{rst}')]);sch=''.join([_ch('CIDRs',', '.join(scope_info.get('allowed_cidrs',()))),_ch('Domains',', '.join(scope_info.get('allowed_domains',()))),_ch('Commands',', '.join(scope_info.get('allowed_commands',()))),_ch('Merkle Root',mr)])
  gch=''.join([_ch('Agent',', '.join(ags)),_ch('Model',', '.join(mds)),_ch('Shield',f'{pb} Blocked'),_ch('Breaker',cb_st)]);fch=''.join([_ch('Merkle Root',mr),_ch('Leaves/Depth',f"{int(mi.get('leaf_count', 0))}/{int(mi.get('tree_depth', 1))}"),_ch('SARIF',f"S={int(sc.get('PENT20-SCOPE-001', 0))} P={int(sc.get('PENT20-PROMPT-002', 0))} D={int(sc.get('PENT20-DLP-003', 0))} C={int(sc.get('PENT20-CIRCUIT-004', 0))}")]);sigc=''.join((_ch(k,v)for k,v in[('Report',signature.get('report_file','SESSION_REPORT.md')),('SHA-256',signature.get('content_sha256','-')),('HMAC-SHA256',signature.get('hmac_sha256','-')),('Key',signature.get('key_fingerprint','-'))]));tabs=''.join((f"""<button type="button" class="tab-btn{(' active' if i == 0 else '')}" role="tab" aria-selected="{('true' if i == 0 else 'false')}" onclick="switchTab('{tid}',this)">{lbl}</button>""" for i,(tid,lbl)in enumerate([('overview','1. Executive Overview &amp; Telemetry'),('mitre','2. MITRE ATT&amp;CK &amp; Live Timeline'),('governance','3. AI Governance &amp; Prompt Shield'),('forensic','4. Cryptographic &amp; Forensic Verification')])));return f"""<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><title>PENT-20 - {_esc(scope_info.get('session_id', ''))}</title><style>{_CSS}</style></head><body><div class="c"><header class="hd"><div><h1>PENT-20 Pentest Session Scribe Command Center</h1><div class="hm">Session: {_cd(scope_info.get('session_id', '-'))} &bull; Scope: <b>{_esc(scope_info.get('name', '-'))}</b> &bull; UTC: {_cd(generated_at)}</div></div><div class="pg"><div class="ps bc">COMPLIANCE: {score}/100</div><div class="ps {('bg' if cok else 'br')}">{_esc(f'AUDIT CHAIN: {chain_result.status} ({chain_result.verified_entries}/{chain_result.total_entries})')}</div></div></header><nav class="tb" role="tablist">{tabs}</nav><div id="tab-overview" class="tab-panel active"><section class="gd">{kpis}</section>{_sec('Scope Policy', _b('bc', 'FAIL-CLOSED'), f'<div class=gd>{sch}</div>')}</div><div id="tab-mitre" class="tab-panel">{_sec('MITRE ATT&amp;CK Ledger', _b('bc', 'DLP+GUARD'), _tbl(('Seq', 'UTC', 'Target', 'Command', 'MITRE', 'Tactic', 'Risk', 'DLP', 'Status', 'Output'), steps))}</div><div id="tab-governance" class="tab-panel">{_sec('AI Governance &amp; Prompt Shield', _b('bp', 'SHIELD'), f'<div class=gd>{gch}</div>' + _tbl(('Seq', 'Event', 'Target', 'Command', 'Actor', 'Details'), shs) + _tbl(('Seq', 'Agent', 'Model', 'Tool', 'Approved', 'Hash', 'Reasoning'), ais))}</div><div id="tab-forensic" class="tab-panel">{_sec('SHA-256 Hash-Chain', _b('bg' if cok else 'br', chain_result.status), f"<div class=cf>{''.join(nodes)}</div>")}{_sec('Merkle, SARIF v2.1.0 &amp; Manifest', _b('bc', f"{int(sarif_summary.get('total_findings', 0))} SARIF"), f'<div class=gd>{fch}</div>' + _tbl(('File', 'Size', 'SHA-256'), mrows))}{_sec('HMAC-SHA256 Signature', _b('bg', 'SIGNED'), f'<div class=gd>{sigc}</div>')}</div><div class="ft">PENT-20 &bull; {_esc(scope_info.get('authorization', '-'))}</div></div><script>{_JS}</script></body></html>\n"""
 def write(self,*,html_path,**kw):d=Path(html_path);d.parent.mkdir(parents=True,exist_ok=True);d.write_text(self.render(**kw),encoding='utf-8');return d
def generate_html_dashboard(*,html_path,**kw):return HTMLDashboard().write(html_path=html_path,**kw)
